with d as (select value r from jsonb_array_elements($q$[{"notes":["Tepsi galay is best served warm from the dish. If you don't have an ovenproof dish, brown the meat in a frying pan and transfer to a large baking dish before adding the other ingredients.","The okra really does need to go in at the end, if you add it earlier it will break down and make the sauce slimy. Don't stir once the okra is in.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"id":"0e53d2ca-c88c-48db-b821-7a3e1944e3dc"},{"notes":["Make it fresh each time, sambal matah is best eaten within an hour of pounding, while the shallots still have bite.","Adjust the heat by using fewer chillies, or add a splash more lime juice if you prefer it sharper than hot."],"steps":[{"text":"Combine the sliced shallots, chopped bird's eye chillies and sliced garlic in a mortar or bowl."},{"text":"Using a pestle or the back of a spoon, gently pound to release the oils and aromas, about 1 to 2 minutes, until the ingredients are bruised, glistening and beginning to break down. You want them bruised, not completely crushed."},{"text":"Stir in the lime juice, neutral oil and salt. Taste and adjust salt or lime to your liking, it should be sharp, hot and bright."},{"text":"Leave to sit for a few minutes before serving so the flavours marry, then stir through fresh coriander if you like. Serve at room temperature with rice, grilled fish or sate."}],"id":"249ec2e8-86ac-489d-b5d0-b88b82542cf3"},{"steps":[{"text":"Line a fine sieve with cheesecloth or a clean tea towel. Pour the yoghurt into it, add the salt, and stir gently to combine. Tie the corners of the cloth together and hang it over a bowl (or suspend it in the fridge) to drain overnight, or for at least 12 hours, until the whey has stopped dripping. You want all the whey to drip away; the longer it strains, the thicker and more cheese-like the labaneh becomes."},{"text":"Once drained, the labaneh will be thick and creamy. Scrape it into a bowl and stir it smooth. You can serve it at this point, or for a richer texture and more authentic presentation, roll it into balls about the size of walnuts. Chill them for at least 1 hour so they hold their shape."},{"text":"Just before serving, arrange the balls on a plate or in a shallow dish. Sprinkle the za'atar evenly over the top, then drizzle generously with olive oil. The za'atar will stick to the oil and stay bright. Serve immediately with warm flatbread or pita for dipping, the bread is how you eat labaneh, never with a spoon alone."}],"id":"fb054b34-3968-4ec8-baa3-4b8de46cc29c"},{"steps":[{"text":"Rinse the sushi rice under cold water until the water runs almost clear. Cook in 360 ml water in a rice cooker or pot, about 15 minutes for a cooker or 20 minutes on the stove with the lid on."},{"text":"While the rice cooks, bring the dashi, soy sauce, caster sugar, mirin and sake to a gentle simmer. Carefully open each tofu pouch along the folded edge with your fingernail or a small knife, then slide them into the liquid. Poach for 8 to 10 minutes until they absorb the broth and soften, turning halfway. Set aside to cool until you can handle them, about 5 minutes."},{"text":"As the rice finishes, whisk the rice vinegar, salt and caster sugar together. Turn the hot rice into a shallow bowl and gently fold in the vinegar mixture, using a wooden spatula to cool it as you fold. This takes about 5 minutes. Let it rest while you prepare the filling."},{"text":"Dice the carrot, daikon and mushroom very finely, about the size of a sesame seed. If you like, blanch them in boiling water for 1 minute, then drain well. This keeps them crisp."},{"text":"Fold the diced vegetables, pickled ginger if using, sesame seeds, salt and white pepper gently through the cooled rice."},{"text":"Gently squeeze the tofu pockets to remove any excess broth. Hold one open and, using a small spoon, carefully fill each pocket with a modest amount of rice mixture, it should be gentle and not packed tight. The pocket should be full enough to hold its shape but not bursting."},{"text":"Arrange the filled pockets, seam-side up, on a plate. Serve at room temperature."}],"id":"a972ada1-da68-46cf-a3c0-c53e62524f0a"},{"notes":["Cassava fries are best eaten fresh and hot. If making ahead, reheat them in a 180°C oven for 5 minutes to restore crispness.","Don't skip soaking the cassava, it removes starch and makes the fries crispier."],"id":"da71901c-b669-479d-8c44-1e5724fff965"},{"notes":["Serve with crusty bread to soak up the sauce, or over rice or mash.","Makes great leftovers. Cool and store in the fridge for up to 3 days.","Works just as well in a camp oven at low heat, about 3 hours if the coals are right."],"id":"700238ad-81c1-4348-8789-ca88a30e50cd"},{"notes":["Make this a day ahead if you like, the flavour deepens overnight. Reheat gently on the stove or in a 160°C oven until warmed through.","Native pepper is available from good delis and spice shops, but if you can't find it, use a grind of black pepper instead.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Preheat the oven to 160°C. Pat the beef cheeks dry with paper towel, then season with salt and pepper."},{"text":"Heat the oil in a large heavy-bottomed pot or casserole dish over medium-high heat. Brown the beef cheeks in batches, 3 to 4 minutes each side, until golden. Transfer to a plate."},{"text":"Add the onions to the pot and cook until just coloured, about 4 minutes. Add the carrots and parsnips and stir for 2 minutes."},{"text":"Return the beef cheeks to the pot. Pour in the tinned tomatoes and beef stock, and add the bay leaves and thyme. The liquid should mostly cover the beef. Bring to a simmer until gentle bubbles break the surface."},{"text":"Cover and transfer to the oven. Cook for 3 hours, turning the beef cheeks halfway through, until they are very tender and the meat shreds easily with a fork."},{"text":"Remove from the oven. Stir through the ground native pepper. Taste and adjust seasoning with salt and pepper. Divide among bowls, spoon the gravy and vegetables over, and finish with a light grind of native pepper."},{"text":"Serve with mashed potato or crusty bread."}],"id":"0d9f69a3-fdc2-4bb6-bd5d-067197bb46a4"},{"notes":["Flaki tastes even better the next day. Make it ahead and reheat gently before serving.","Tripe should be cleaned already when you buy it, but if you have any doubt, rinse it well under cold water and rub gently with salt.","Some Kraków cooks add a little strong mustard or horseradish at the end. It's optional."],"id":"6932fc59-670d-48f6-a4e5-9a3dc74460d0"},{"notes":["This keeps well in the fridge for 2 days and reheats gently, add a splash of milk if it's thickened too much.","Traditionally you'd use the poaching liquid, as this recipe does."],"steps":[{"text":"Put the smoked haddock in a large saucepan with the milk and bay leaves. Bring gently to a simmer and cook for 8 minutes until the fish is just cooked through. Lift the fish out onto a plate, discard the skin and any bones, and break the flesh into flakes. Keep the milk in the pan."},{"text":"In a separate pan, melt the butter and cook the chopped onion gently, stirring occasionally, until soft and pale, about 5 minutes."},{"text":"Add the diced potatoes to the buttered onion and stir to coat. Pour in the reserved milk with the bay leaves, bring to a simmer and cook for about 12 minutes until the potatoes are tender."},{"text":"Return the flaked haddock to the pan, add the cream and stir gently. Heat through for 2–3 minutes without boiling."},{"text":"Season with salt and pepper to taste, go easy on the salt as the smoked fish is already quite salty. Serve hot, scattered with fresh parsley if you like."}],"id":"55b55b1b-d706-407a-af45-24c3bce283f6"},{"notes":["Make ahead: This actually tastes better the next day. Cool quickly, store in the fridge for up to 3 days, or freeze for up to 2 months. Add a splash of water when you reheat.","Brown lentils hold their shape better than red; French lentils work too. Skip the fancy stuff, everyday brown lentils from the market are perfect."],"id":"fcc4ff98-09d0-4068-9c82-add53a836973"},{"notes":["Best made the day before and reheated, the flavours deepen overnight.","Serve with Swedish mustard, rye bread, and a shot of aquavit if you're so inclined.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"steps":[{"text":"Rinse the split peas in cold water and drain. Place the pork, water, and bay leaf in a large pot and bring to a boil until a grey foam rises to the surface. Skim off any foam from the surface."},{"text":"Add the split peas, onions, carrots, and celery. Stir in the peppercorns and salt."},{"text":"Reduce the heat to low and simmer, partially covered, for about 2 hours, stirring occasionally. The peas should break down into the broth and the pork should be very tender."},{"text":"Taste and adjust seasoning with salt as needed. Serve hot in bowls with rye bread and Swedish mustard on the side."}],"id":"284deda7-6597-47c8-98e8-699d61f7e9dd"},{"notes":["Keep this in an airtight container in the fridge for up to 4 days, it reheats gently and actually improves as the flavours settle. Make it in bulk and freeze portions.","If you prefer less sweetness, use just 1 tbsp golden syrup, or substitute a splash of apple juice instead."],"id":"3546cff3-080b-481c-943e-0890d9d78c85"},{"notes":["Halwa keeps in an airtight container for 3–4 days. You can reheat it gently in a pan with a splash of water if it dries out.","The toasting of the semolina is important, it takes time but the flavour change is worth it. Don't rush it."],"steps":[{"text":"Heat the ghee in a large, heavy-based saucepan over medium heat. Add the semolina and stir constantly, breaking up any lumps. Toast for 8–10 minutes, stirring often, until the semolina is golden and smells nutty."},{"text":"Add the crushed cardamom pods and salt, stirring for 30 seconds to release the flavour."},{"text":"Carefully pour in the water, it will bubble, and stir constantly to combine. The mixture will be thick and pasty."},{"text":"Add the caster sugar and stir until it dissolves completely into the semolina mixture, about 2 minutes."},{"text":"Remove from the heat and fold through most of the almonds and raisins, reserving some for the top."},{"text":"Spoon the halwa into a serving dish and smooth the surface. Scatter the remaining almonds and raisins over the top."},{"text":"Let it cool to warm, then serve. It sets as it cools but stays soft inside."}],"id":"905a18c9-fc62-4d95-861b-9b997cb65f50"},{"notes":["Make this ahead: gumbo tastes even better the next day. Reheat gently on the stove, and stir in the filé powder just before serving.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large, heavy-bottomed pot over medium heat. Add the flour slowly, stirring constantly with a wooden spoon. Keep stirring, don't walk away, until the roux is deep chocolate brown, about 30 to 40 minutes. It'll go from light tan to darker shades; when it smells nutty and toasted, you're close."},{"text":"Add the onion, celery and capsicum to the roux. Stir well and cook, stirring often, until the vegetables are soft and golden, about 8 minutes."},{"text":"Add the chicken and sausage. Stir to coat with roux, and cook for 5 minutes."},{"text":"Pour in the stock slowly, stirring constantly until smooth to break up any lumps. Add the bay leaf, thyme and cayenne. Bring to a simmer, then reduce heat to low."},{"text":"Simmer gently, uncovered, for about 40 minutes, until the chicken is cooked through and the flavours have melded. Skim any fat from the surface if you like."},{"text":"Taste and season with salt and pepper. Remove from heat and stir in the filé powder until smooth. Don't boil after adding filé, or it gets stringy."},{"text":"Serve in bowls over white rice, scattered with spring onion if you like."}],"id":"50c05896-857b-407f-b9bc-eb72f5fcad18"},{"notes":["Tastes even better the next day. Reheat gently on the stove.","Traditional Colombian comfort food: serve with white rice and avocado on the side.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"4789d99e-a533-4789-a3be-1766c886c02d"},{"notes":["Make a bigger batch of ful and store it in the fridge for 3 days; reheat gently with a splash of water.","Use tinned or cooked dried fava beans, the tinned kind saves time and money if you're cooking on a weeknight.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"3484d045-923a-437e-96dc-1a7cd1301e19"},{"steps":[{"text":"Soak the pine nuts in warm water for 15 minutes, then drain well."},{"text":"In a bowl, combine the drained pine nuts, shiitake, carrot, potato, and spring onion whites. Stir in the minced ginger, sesame oil, soy sauce, rice vinegar and a pinch of salt until everything is evenly coated."},{"text":"Prepare a steamer by bringing water to a simmer in a pot until steam is rising steadily. Transfer the pine nut mixture to a heatproof bowl or steaming plate that fits in your steamer."},{"text":"Steam over simmering water for 20 to 25 minutes, until the potato is tender and the pine nuts have softened but still hold their shape."},{"text":"Remove from the steamer and let cool to room temperature. Scatter the spring onion greens and toasted sesame seeds over the top."},{"text":"Serve at room temperature in small bowls."}],"id":"838b931c-ff3f-4c04-8a3f-eccba5bac72c"},{"notes":["Make sure to press the tofu well, this is key to getting it crispy. Soft tofu won't work; stick with extra-firm.","You can prep the tofu cutlets and coat them hours ahead, then fry just before serving.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Press the tofu between kitchen towels or in a tofu press for at least 15 minutes to remove excess moisture."},{"text":"Slice the pressed tofu block in half lengthways, then slice each half in half again to create two thick, flat cutlets. Pat dry with paper towels."},{"text":"Set up three shallow bowls: one with plain flour, one with beaten egg, and one with panko breadcrumbs."},{"text":"Season the tofu cutlets lightly with salt and pepper on both sides."},{"text":"Coat each cutlet in flour, shaking off excess, then dip in egg, then press firmly into panko until completely coated on both sides."},{"text":"Heat about 1 cm of neutral oil in a large frying pan over medium-high heat until shimmering."},{"text":"Once the oil is hot, carefully place the tofu cutlets in the pan and fry for 3–4 minutes per side, until the panko is golden brown and crispy. Don't move them around too much, let them sit so they get a good crust."},{"text":"Transfer to a plate lined with paper towels to drain any excess oil."},{"text":"Drizzle tonkatsu sauce generously over the top of each cutlet and serve immediately with pickled cabbage and steamed white rice on the side."}],"id":"a68153fc-aba1-4a31-adee-dcfaf56cef45"},{"notes":["Make the rolls up to 3 hours ahead and keep them covered with a damp cloth at room temperature. Steam just before serving.","If you don't have a non-stick crêpe pan, use a small non-stick frying pan and work quickly, the batter sets fast.","Bánh cuốn freezes well before steaming: place rolls on a tray lined with baking paper, freeze until firm, then pack in an airtight container for up to 1 month. Steam straight from frozen, adding 2 to 3 minutes to the cooking time.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"523b0666-f3a1-4459-8bbc-52258850e7a8"},{"notes":["Escabeche is even better the day after you make it, the fish stays moist and the flavours marry beautifully. Cover and keep in the fridge for up to 3 days.","If you can't find barramundi or flathead, any firm white fish works well. Avoid delicate fish like basa.","This is a dish built for sharing. Take it out of the fridge 20 minutes before serving to let the oil loosen up a bit.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"0da133d7-7c10-4d55-82f7-2e45f9b821cf"},{"notes":["Andouillettes are sold fresh at good butchers and some French delis. If you can't find them, they're not worth substituting, save this recipe for when you do.","The success of the dish depends on getting the sausage skin crispy in the pan. Don't crowd them, and don't fidget with them while they cook.","Serve with mustard-roasted potatoes or a simple green salad to cut through the richness.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"7e9998ec-8fae-48cc-a5c9-baada1b5f3da"},{"notes":["Make the ragù on Sunday to let the flavours deepen overnight. You'll have leftovers, which freeze well.","If you don't have fresh mozzarella, use fior di latte or even a cube of cold butter instead.","Arancini can be coated and refrigerated for up to 12 hours before frying. This actually helps them hold their shape better.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the ragù: heat oil in a heavy-based pot, add diced onion and cook gently until soft, about 5 minutes. Add beef and pork mince, stirring to break it up, until browned, about 8 minutes. Pour in wine and let it bubble away for 2 minutes. Add crushed tomatoes, season with salt and pepper, then lower heat and simmer gently, uncovered, for at least 30 minutes (longer is better). The ragù should be thick and the flavours rich. Let cool completely."},{"text":"Make the risotto: bring stock to a gentle simmer in a separate pot and keep it there. In a heavy-based pan, melt butter over medium heat, add diced onion and cook until soft and golden, about 5 minutes. Add rice and stir constantly for 1 minute until the grains are coated and lightly toasted. Pour in wine and stir until absorbed."},{"text":"Add stock one ladleful at a time, stirring often, letting each addition absorb before adding the next. After about 18 minutes, the rice should be creamy and just tender. Stir in parmesan and season with salt and pepper. Spread the risotto on a large tray to cool to room temperature, about 20 minutes."},{"text":"Once risotto is cool, mix in 200 g (about half) of the ragù and all the thawed peas. Wet your hands and shape the mixture into 12 balls, each about the size of a golf ball. Make an indent in the centre of each ball with your thumb, press in a cube of mozzarella and a generous pinch of the remaining ragù, then seal the opening and reshape into a smooth ball. This takes patience but it's what keeps the filling hidden inside."},{"text":"Set up three shallow bowls: one with beaten eggs, one with panko breadcrumbs, and one empty. Roll each arancino ball in egg, then roll in breadcrumbs until well coated. Place on a tray and chill for at least 30 minutes (or up to 12 hours) so the coating sets firmly."},{"text":"Heat oil in a deep, heavy-based pot or deep-fryer to 170°C. If you don't have a thermometer, test with a wooden spoon handle: it should sizzle gently at the edge of the oil. Fry arancini in batches of 3–4, turning occasionally, for 3–4 minutes until golden brown all over. Don't crowd the pan. Remove with a slotted spoon and drain on paper towel."},{"text":"Serve warm, while the mozzarella inside is still soft and the outside is crispy. Arancini are best eaten fresh but are still good at room temperature."}],"id":"7b0adbd4-b2ec-4801-ba02-3259897d2447"},{"steps":[{"text":"Drain and pat the salt cod dry. Cut into 4 thick pieces, about 150 g each."},{"text":"Heat 100 ml olive oil in a wide, shallow earthenware dish (cazuela) or heavy-based pan over very low heat. Add the sliced garlic and red chilli (if using). Cook gently, stirring, until the garlic is fragrant and just beginning to soften, about 2 minutes. Don't let it brown."},{"text":"Lay the salt cod pieces skin-side up in the warm oil. The oil should just barely cover them, add a little more if needed. Keep the heat very low and poach gently, uncovered, for 5–7 minutes. The cod will begin to flake at the edges and turn opaque."},{"text":"Now the critical part: remove the pan from the heat and let it cool for 1 minute. Using a wooden spoon or your wrist in a smooth, circular motion, begin tilting and rotating the pan while gently stirring the cod in the oil. The gelatine from the fish will start to emulsify the oil into a creamy sauce."},{"text":"Return the pan to very low heat and continue this tilting and stirring motion. Gradually add the remaining 100 ml olive oil in a thin stream while rotating and tilting, as if you were making a sauce. The emulsion builds slowly, this is the pil-pil. Keep going for 8–10 minutes until the sauce is pale, silky and creamy."},{"text":"Taste and season with salt if needed. Serve in the pan, spooning the creamy pil-pil sauce over the cod. Scatter with fresh parsley if you like."}],"id":"aa310052-38a0-44ee-a010-b2d67d6aaac6"},{"notes":["Baklava keeps in an airtight container for up to 5 days. The pastry stays crisp and the flavours deepen.","Use room-temperature syrup on hot baklava, not the other way around, this is what makes it properly absorb.","Pistachios are traditional, but walnuts or almonds work if that's what you have. Just chop them fine."],"steps":[{"text":"Make the syrup first: combine water, sugar, cinnamon stick, cloves and lemon slice in a saucepan. Bring to a boil, then reduce heat and simmer for 10 minutes. Remove from heat, stir in honey, and set aside to cool to room temperature."},{"text":"Preheat oven to 175°C. Mix pistachios with caster sugar and ground cinnamon in a bowl."},{"text":"Brush a 33 x 23 cm baking dish generously with melted butter. Lay down one yufka sheet and brush with butter. Repeat until you have 6 layers, this is your base."},{"text":"Spread a thin, even layer of pistachio mixture over the top sheet. Layer 2 more yufka sheets on top, brushing each with butter."},{"text":"Repeat the pistachio layer and 2 more yufka sheets. Keep going until you've used most of your pistachios, finishing with at least 6 yufka sheets on top, each brushed with butter."},{"text":"Using a sharp knife, cut the baklava into diamond or triangular pieces all the way through to the base, about 20 pieces total. Pour any remaining melted butter over the top."},{"text":"Bake for 35 to 40 minutes, until golden brown and the edges are darker. You'll hear it starting to crisp as it cools."},{"text":"Remove from oven and immediately pour the room-temperature syrup slowly and evenly over the hot baklava. It will sizzle and soak in. Let cool completely in the pan, at least 2 hours, before serving."}],"id":"df8cd59e-27cb-409a-ab4c-fc77f2d42a6c"},{"notes":["Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"5d2a27d5-beb0-410e-a5b6-bbc9babaf060"},{"notes":["The noodle cakes can be formed up to 2 hours ahead; stack them between sheets of baking paper and refrigerate. Grill straight from the fridge, adding 1–2 minutes per side.","If your grill pan is small, grill the components in batches and keep them warm on a plate in a low oven (120°C) while you finish cooking.","The pork belly will spit as the fat renders, keep the heat steady and watch closely after the 2-minute mark to avoid burning.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"steps":[{"text":"Pour chicken stock into a saucepan and bring to a simmer. Add rice vermicelli and cook until just tender, about 3 minutes, stirring occasionally. The noodles will be soft and may break slightly, this is right. Drain in a fine sieve and spread on a tray to cool to room temperature, about 10 minutes."},{"text":"While the noodles cool, make the dipping sauce: stir fish sauce, lime juice and sugar together in a small bowl until the sugar dissolves. Set aside."},{"text":"Divide the cooled noodles into 8 equal portions. Take one portion and press it gently on an oiled piece of baking paper, forming a flat rectangle about 15 cm × 10 cm and roughly 1 cm thick. Do not press too hard or the cake will become dense. Repeat with the remaining noodle portions."},{"text":"Heat a large grill pan or outdoor grill to medium-high heat until very hot and a drop of water sizzles on contact. Brush the grill grates lightly with oil."},{"text":"Carefully transfer one noodle cake to the hot grill (start with the baking paper if using, then slide it away). Grill until the underside is golden and charred in patches, about 3–4 minutes. Flip carefully and grill the other side until golden and crispy, another 2–3 minutes. Transfer to a warm plate. Repeat with the remaining noodle cakes."},{"text":"On the same grill or a separate pan at medium-high heat, grill the pork belly slices for 2–3 minutes per side until the fat has rendered and the edges are crisp and caramelised. The pork should be cooked through with no pink remaining. Transfer to a warm plate."},{"text":"Grill the prawns over medium-high heat for 1–2 minutes per side until they are opaque throughout and have a light char. Transfer to a warm plate."},{"text":"Arrange one noodle cake on each serving plate. Tear or arrange the grilled pork belly and prawns over the top. Garnish with fresh coriander if using and serve immediately with lime wedges and the fish sauce dipping sauce on the side."}],"id":"f775e7c0-4062-4151-b277-0c643d6f900e"},{"notes":["Make the fish sauce mayo and prepare the pickled daikon up to a day ahead; toast the baguette and cook the pork just before eating.","The pork can marinate for up to 2 hours in the fridge for deeper flavour, but 15 minutes is enough for a quick lunch.","If you can't find pickled daikon, use pickled mustard greens or a mix of pickled vegetables, the acid and brightness matter more than the exact vegetable.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages).","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Mix fish sauce, palm sugar, garlic, lemongrass and ground coriander in a bowl. Add the pork slices and toss to coat. Let sit for at least 15 minutes (or up to 2 hours in the fridge)."},{"text":"Combine mayonnaise, fish sauce and lime juice in a small bowl, stirring until smooth. Taste and adjust seasoning."},{"text":"Heat a large frying pan or grill pan over high heat until it's smoking hot. Working in batches if needed, cook the pork until the edges are charred and caramelised, about 2–3 minutes per side. Don't move the pieces around, let them sit so they get a dark, crusty exterior. Set aside on a plate."},{"text":"Lightly toast the baguette cut-side down in the same hot pan for about 1 minute, until golden and crispy."},{"text":"Spread the fish sauce mayo on the cut side of each baguette. Layer the charred pork, then pickled daikon, fresh coriander and chilli. Season with salt and pepper. Serve immediately while the bread is still warm."}],"id":"0ba92b1c-1712-4d6c-a1c7-73dc95b3f1af"},{"notes":["Slice the beef when it's partially frozen (about 30 minutes in the freezer) for cleaner, thinner cuts.","This is best served immediately. The beef toughens if it sits in the wok too long, aim for 2 minutes total cooking time from wok to plate.","If you can't find fermented black beans (douchi), use 2 tbsp more oyster sauce and a pinch of extra salt, though it won't be quite the same dish.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Slice the beef thinly against the grain and set aside. Rinse the black beans, drain well, and chop roughly. Slice the garlic and chilli."},{"text":"Heat the wok over high heat until smoking, about 2 minutes. Add 1 tbsp oil, swirl to coat."},{"text":"Working quickly, add half the beef and let it sit for 30 seconds without stirring, this helps it catch colour. Toss for 30 seconds, then transfer to a plate. Repeat with the remaining oil and beef."},{"text":"Return the wok to high heat. Add the garlic and chilli, toss for 10 seconds until fragrant. Add the black beans, toss for another 10 seconds."},{"text":"Return all the beef to the wok with the oyster sauce and sesame oil. Toss everything together for 30 seconds, until coated and heated through."},{"text":"Serve immediately over steamed rice, scattered with spring onion."}],"id":"237da146-0a87-43a1-b2f1-cfef338e544d"},{"notes":["Make the broth a day ahead for deeper flavour; reheat gently and add the sausage and noodles to serve.","The blood sausage is traditional, but if you can't find it, add extra beef shin or pork instead.","Central Vietnamese bún bò is spicier than northern versions, add more chillies to your bowl to taste.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"5ffc454f-86a8-40eb-8777-d394abfb998f"},{"notes":["Use only the freshest sashimi-grade fish. Ask your fishmonger for corvina or snapper that's been kept for raw preparation.","The ceviche is at its best eaten within 30 minutes of mixing, the acid continues to work and the texture gets softer the longer it sits.","Make the ají amarillo paste fresh if you can find the chillies; if using paste from a jar, start with 3 tbsp and adjust to taste.","The fish here is eaten raw or only cured in citrus. Buy sashimi-grade fish from a fishmonger, keep it cold and eat it the same day; skip it for anyone pregnant, very young, elderly or with low immunity.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Soak the sliced red onion in salt water (about 1 tsp salt per 250 ml water) while you prepare the fish. This takes the edge off the raw onion and cures it slightly, about 5 minutes."},{"text":"Blend the ají amarillo with the garlic clove and 2 tbsp of the fresh lime juice until smooth. Pass through a fine sieve if you want a completely silky sauce."},{"text":"Put the fish cubes in a glass or ceramic bowl. Add the ají amarillo paste, the remaining lime juice, and a pinch of salt. Stir gently to coat all the fish. Let sit for 10–15 minutes, the lime juice will turn the fish opaque and firm. Taste and adjust salt."},{"text":"Drain the cured red onion and gently fold it into the ceviche just before serving, along with any juice from soaking."},{"text":"Serve in chilled bowls with fresh coriander and toasted corn kernels scattered over the top. Eat while the ceviche is at its brightest, don't leave it sitting or the acid will keep breaking down the fish."}],"id":"b91019d5-51bc-4662-b061-9440a98f914e"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;